INSERT INTO "commerce"."pages" ("added_at","last_updated_at","website_id","slug","title","description","content","nav","rank","image_urls","id") VALUES ('2026-09-23 14:00:52.795','2026-09-23 14:05:59.736',8,'about-us','About us','','<p>Welcome to <strong>The Daily Grind</strong> ☕✨, your new favorite neighborhood sanctuary where exceptional coffee meets community. Nestled right in the heart of the city 🏙️, our cafe was born out of a simple passion: to create a warm, welcoming space where people can slow down, connect, and enjoy the finer things in life. From the moment you step through our doors, you will be greeted by the rich, comforting aroma of freshly roasted coffee beans 🫘 and the smiling faces of our passionate baristas 👋. We believe that a great cup of coffee is more than just a morning caffeine fix—it is an experience, a ritual, and a craft.</p><img src="https://wawago.oss-ap-southeast-1.aliyuncs.com/media/0e3bb36458974333b0c2919028e61f55.webp" alt="americano-1024x576.webp"><p>Our carefully curated menu features a wide selection of specialty coffees, all brewed from ethically sourced, 100% Arabica beans 🌍. We partner closely with local roasters to ensure that every espresso, latte, and pour-over we serve highlights the unique flavor profiles of the region it came from ☕️. Whether you prefer a bold, dark roast to kickstart your workday 💼 or a smooth, velvety flat white to enjoy alongside a good book 📚, our team takes pride in crafting the perfect cup just for you. For those looking for something different, we also offer a premium selection of loose-leaf herbal teas 🫖, refreshing iced botanicals 🍹, and rich, house-made hot chocolates 🍫.</p><img src="https://wawago.oss-ap-southeast-1.aliyuncs.com/media/ad2f300a13104ac7b78b6d65baf5c047.jpg" alt="How-Much-Caffeine-Is-in-Black-Tea.jpg"><p>But we are more than just a coffee shop! The Daily Grind is a culinary haven featuring a daily rotation of artisanal pastries 🥐, hearty breakfast sandwiches 🥪, and wholesome lunch options. Everything on our menu is prepared fresh daily using locally sourced, organic ingredients whenever possible 🌱. From flaky, buttery croissants baked at dawn to vibrant, seasonal avocado toasts 🥑 and indulgent gluten-free treats 🍰, there is always something delicious to satisfy your cravings.</p><img src="https://wawago.oss-ap-southeast-1.aliyuncs.com/media/3f0317ee733f4493bd35edf364e66b78.jpg" alt="gorenje-blog-refreshing_cold_brew_coffee.jpg"><p>The space itself is designed with your absolute comfort in mind 🌿🛋️. Featuring a blend of rustic charm and modern minimalism, our cafe boasts an abundance of natural light ☀️, cozy plush seating, and quiet corners equipped with high-speed internet 💻—making it the ideal spot for remote work, casual business meetings, or catching up with old friends. Whether you are grabbing a quick cold brew to go 🏃‍♂️💨, settling in for a productive afternoon of writing, or gathering with loved ones for a relaxed weekend brunch 🥂, we invite you to make our space your own. Come on in, find your favorite spot, and let us pour you a little bit of happiness! 🥰🎉</p>',true,2,'{"https://wawago.oss-ap-southeast-1.aliyuncs.com/media/0e3bb36458974333b0c2919028e61f55.webp","https://wawago.oss-ap-southeast-1.aliyuncs.com/media/ad2f300a13104ac7b78b6d65baf5c047.jpg","https://wawago.oss-ap-southeast-1.aliyuncs.com/media/3f0317ee733f4493bd35edf364e66b78.jpg"}',4) RETURNING "id";
